function longestMountain(arr) {
  const n = arr.length;
  let best = 0;
  let start = 0;

  while (start < n) {
    let end = start;
    if (end + 1 < n && arr[end] < arr[end + 1]) {
      while (end + 1 < n && arr[end] < arr[end + 1]) {
        end++;
      }
      if (end + 1 < n && arr[end] > arr[end + 1]) {
        while (end + 1 < n && arr[end] > arr[end + 1]) {
          end++;
        }
        best = Math.max(best, end - start + 1);
      }
    }
    start = Math.max(end, start + 1);
  }
  return best;
}

