function longestMountain(arr) {
  const isMountain = (from, to) => {
    if (to - from + 1 < 3) return false;
    let k = from;
    while (k < to && arr[k] < arr[k + 1]) k++;
    if (k === from || k === to) return false;
    while (k < to && arr[k] > arr[k + 1]) k++;
    return k === to;
  };
  let answer = 0;
  for (let from = 0; from < arr.length; from++)
    for (let to = from + 2; to < arr.length; to++)
      if (isMountain(from, to)) answer = Math.max(answer, to - from + 1);
  return answer;
}

