function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const top = pick(1, 5);
    return [Array.from({ length: n }, () => pick(0, top))];
  }
  // Large: a walk made of rising, falling and flat runs so that real mountains appear.
  const n = 2000;
  const arr = [];
  let value = pick(0, 10000);
  while (arr.length < n) {
    const mode = rand();
    const run = pick(1, 60);
    for (let k = 0; k < run && arr.length < n; k++) {
      if (mode < 0.45) value = Math.min(10000, value + pick(1, 50));
      else if (mode < 0.9) value = Math.max(0, value - pick(1, 50));
      arr.push(value);
    }
  }
  return [arr];
}
